return [
    'page_title' => 'விதிமுறைகள் & நிபந்தனைகள்',
    'last_updated' => 'கடைசியாகப் புதுப்பிக்கப்பட்டது :date',
    's1_title' => '1. இந்த விதிமுறைகளுக்கு ஒப்புதல்.',
    's1_body' => 'இந்த விதிமுறைகள் & நிபந்தனைகள் ("விதிமுறைகள்") எங்கள் இணையதளம், மொபைல் அனுபவம் மற்றும் கணக்கு, பணம் செலுத்துதல், அட்டை, ஆதரவு தொடர்பான அனைத்து வசதிகள் உட்பட (ஒன்றாக "சேவை") Ledger-ஐ நீங்கள் அணுகுவதையும் பயன்படுத்துவதையும் நிர்வகிக்கின்றன. கணக்கை உருவாக்குவதன் மூலமோ சேவையைப் பயன்படுத்துவதன் மூலமோ, இந்த விதிமுறைகளுக்கும் அவற்றில் குறிப்பிடப்பட்டுள்ள கொள்கைகளுக்கும் கட்டுப்பட ஒப்புக்கொள்கிறீர்கள். நீங்கள் ஒப்புக்கொள்ளவில்லை எனில், கணக்கை உருவாக்கவோ சேவையைப் பயன்படுத்தவோ வேண்டாம்.',
    's2_title' => '2. தகுதி.',
    's2_body' => 'Ledger கணக்கைத் திறக்கவும் வைத்திருக்கவும் நீங்கள் குறைந்தது 18 வயதுடையவராக இருக்க வேண்டும், கட்டுப்படுத்தும் ஒப்பந்தம் செய்யும் திறன் இருக்க வேண்டும், கேட்கப்படும்போது அரசால் வழங்கப்பட்ட செல்லுபடியாகும் அடையாள ஆவணத்தையும் நிரந்தர வசிப்பிட முகவரியையும் வழங்க முடிய வேண்டும். உங்கள் அடையாளத்தைச் சரிபார்க்க முடியாவிட்டால், நீங்கள் அரசுத் தடை அல்லது கண்காணிப்புப் பட்டியலில் இருந்தால், அல்லது கணக்கைத் திறப்பதோ வைத்திருப்பதோ Ledger-ஐ சட்ட அல்லது ஒழுங்குமுறை அபாயத்துக்கு உள்ளாக்கினால், கணக்கைத் திறக்க மறுக்கலாம் அல்லது இருக்கும் கணக்கை மூடலாம்.',
    's3_title' => '3. உங்கள் கணக்கு.',
    's3_body' => 'Ledger கணக்கு இருப்புகளை Ledger ஒரு வங்கியாக நேரடியாக வைத்திருப்பதில்லை. நிதிகள் FDIC காப்பீடு பெற்ற ஒன்று அல்லது அதற்கு மேற்பட்ட கூட்டாளர் வங்கிகளில் ஒருங்கிணைந்த பாதுகாப்புக் கணக்குகளில் வைக்கப்படுகின்றன, மேலும் உங்கள் நிதிகள் பொருந்தும் வரம்பு வரை FDIC-இன் "பாஸ்-த்ரூ" வைப்புக் காப்பீட்டுக்குத் தகுதியானவை; இது FDIC விதிகள், அதே கூட்டாளர் வங்கியில் உங்களுக்குள்ள பிற நிதிகளுடன் ஒருங்கிணைப்பு, கூட்டாளர் வங்கியின் தோல்வி ஆகியவற்றுக்கு உட்பட்டது. Ledger ஒரு நிதித் தொழில்நுட்ப நிறுவனம், உரிமம் பெற்ற வங்கி அல்ல. எழுத்துமூலம் வேறுவிதமாக ஒப்புக்கொள்ளாத வரை நீங்கள் ஒரே ஒரு தனிப்பட்ட கணக்கை மட்டுமே வைத்திருக்கலாம், மேலும் எங்கள் முன் எழுத்துமூல ஒப்புதல் இன்றி ஒரு வணிகம், அறக்கட்டளை அல்லது வேறு நபர் சார்பாக நிதி பெற கணக்கைப் பயன்படுத்தக்கூடாது.',
    's4_title' => '4. அடையாளச் சரிபார்ப்பு மற்றும் கணக்கு வரம்புகள்.',
    's4_body' => 'கணக்கைத் திறக்கும் ஒவ்வொரு நபரையும் அடையாளம் காணும் தகவலைப் பெறவும், சரிபார்க்கவும், பதிவு செய்யவும் கூட்டாட்சிச் சட்டம் நிதிச் சேவை வழங்குநர்களைக் கோருகிறது. புகைப்பட அடையாள ஆவணம், செல்ஃபி அல்லது முகவரிச் சான்று ஆவணத்தைச் சமர்ப்பிக்கக் கேட்கலாம், மேலும் அந்தத் தகவல் மறுஆய்வு செய்யப்பட்டு அங்கீகரிக்கப்படும் வரை பரிமாற்றத் தொகைகள், அட்டை வழங்கல் அல்லது பிற வசதிகளைக் கட்டுப்படுத்தலாம். உங்கள் தகவலை அவ்வப்போது மீண்டும் சரிபார்க்கலாம், புதுப்பிக்கப்பட்ட தகவலுக்கான கோரிக்கைக்குப் பதில் இல்லையெனில் பாதிக்கப்பட்ட வசதிகளை இடைநிறுத்தலாம்.',
    's5_title' => '5. பரிமாற்றங்கள் மற்றும் பணம் செலுத்துதல்கள்.',
    's5_body' => 'சேவை பணத்தை நகர்த்தப் பல வழிகளை ஆதரிக்கிறது, ஒவ்வொன்றும் பரிவர்த்தனையின்போது காட்டப்படும் வரம்புகள், இறுதி நேரங்கள் மற்றும் மறுஆய்வுக்கு உட்பட்டது: (அ) Ledger-இலிருந்து Ledger பரிமாற்றங்கள், Ledger கணக்குகளுக்கு இடையே உடனடியாக அனுப்பப்படும்; (ஆ) வெளி வங்கிப் பரிமாற்றங்கள், அதே நாட்டில் உள்ள இணைக்கப்பட்ட அல்லது தேர்ந்தெடுக்கப்பட்ட வங்கிக்கு அந்த வங்கியின் ரூட்டிங் தகவலைப் பயன்படுத்தி அனுப்பப்படும்; (இ) சர்வதேசப் பரிமாற்றங்கள், உங்கள் சொந்த நாட்டுக்கு வெளியே உள்ள வங்கிக்கு அதன் SWIFT/BIC குறியீடு மற்றும் கணக்கு அல்லது IBAN எண்ணைப் பயன்படுத்தி அனுப்பப்படும், இவை வந்து சேர அதிக நேரம் ஆகலாம், எங்கள் கட்டுப்பாட்டுக்கு வெளியே உள்ள இடைநிலை வங்கிகள் வழியாகச் செல்லலாம், பரிமாற்றம் செயலாக்கப்படும் நேரத்தில் நிர்ணயிக்கப்படும் விகிதத்தில் நாணய மாற்றத்துக்கு உட்படலாம்; (ஈ) கட்டணம் செலுத்துதல், நீங்கள் குறிப்பிடும் பெறுநருக்கு அனுப்பப்படும்; மற்றும் (உ) பணம் எடுத்தல் மற்றும் டாப்-அப், உங்கள் Ledger இருப்புக்கும் இணைக்கப்பட்ட அட்டை அல்லது வெளிக் கணக்குக்கும் இடையே பணத்தை நகர்த்தும். பெறுநர், ரூட்டிங், SWIFT/BIC மற்றும் கணக்கு விவரங்களை முழுமையாகவும் துல்லியமாகவும் உள்ளிடுவது உங்கள் பொறுப்பு — நீங்கள் வழங்கிய விவரங்களுக்குச் சரியாக அனுப்பப்பட்ட பரிமாற்றத்தை, அந்த விவரங்கள் தவறாக இருந்தாலும், Ledger-ஆல் திருப்ப முடியாது. சந்தேகத்துக்குரிய மோசடி, தடைச் சரிபார்ப்பு அல்லது போதுமான இருப்பு இல்லாமை காரணமாகக் குறிக்கப்பட்டால் பரிமாற்றம் தாமதமாகலாம், மறுஆய்வுக்காக நிறுத்தி வைக்கப்படலாம் அல்லது நிராகரிக்கப்படலாம்.',
    's6_title' => '6. திட்டமிடப்பட்ட பரிமாற்றங்கள்.',
    's6_body' => 'எதிர்காலத் தேதிக்குத் திட்டமிடும் பரிமாற்றம் தேர்ந்தெடுக்கப்பட்ட தேதியில் மட்டுமே சமர்ப்பிக்கப்படும், உண்மையில் உங்கள் இருப்பிலிருந்து வெளியேறும் வரை உத்தரவாதம் இல்லை. அந்தத் தேதிக்கு முன் எப்போது வேண்டுமானாலும் கணக்கு வரலாற்றிலிருந்து திட்டமிடப்பட்ட பரிமாற்றத்தை ரத்து செய்யலாம். திட்டமிடப்பட்ட தேதியில் கிடைக்கும் இருப்பு போதவில்லை எனில், பரிமாற்றம் தோல்வியடையும், வரலாற்றில் அவ்வாறே குறிக்கப்படும்; போதுமான நிதி இருப்பதை உறுதி செய்வது உங்கள் பொறுப்பு.',
    's7_title' => '7. கட்டணங்கள்.',
    's7_body' => 'சேவை மூலம் தொடங்கப்படும் Ledger-இலிருந்து Ledger பரிமாற்றங்கள், வெளி வங்கிப் பரிமாற்றங்கள், சர்வதேசப் பரிமாற்றங்கள், பணம் எடுத்தல் அல்லது டாப்-அப்களுக்கு Ledger தற்போது கட்டணம் வசூலிப்பதில்லை. உங்கள் இணைக்கப்பட்ட வங்கி, அட்டை வழங்குநர் அல்லது பெறும் சர்வதேச வங்கி இன்னும் தங்கள் சொந்தக் கட்டணங்களை விதிக்கலாம் — சர்வதேசப் பரிமாற்றங்களில் நாணய மாற்றம், வயர் அல்லது இடைநிலை வங்கிக் கட்டணங்கள் உட்பட — இவை எங்கள் கட்டுப்பாட்டுக்கு வெளியே உள்ளவை, Ledger வசூலிப்பதோ வைத்திருப்பதோ இல்லை. எதிர்காலத்தில் Ledger எந்த வசதிக்கும் கட்டணம் அறிமுகப்படுத்தினால், பரிவர்த்தனையை உறுதிப்படுத்தும் முன் அது உங்களுக்குத் தெரிவிக்கப்படும், அதை விவரிக்க இந்த விதிமுறைகள் புதுப்பிக்கப்படும்.',
    's8_title' => '8. அட்டைகள்.',
    's8_body' => 'உங்கள் Ledger இருப்புடன் இணைக்கப்பட்ட மெய்நிகர் அல்லது நேரடி டெபிட் அட்டையைக் கோரினால், அந்த அட்டை ஒப்புதலுக்கு உட்பட்டது, வழங்கப்பட்டதும் ஒவ்வொரு கொள்முதலின்போதும் உங்கள் கிடைக்கும் இருப்பிலிருந்து நேரடியாகக் கழிக்கும் — இது கடன் வரம்பு அல்ல. தொலைந்த, திருடப்பட்ட அல்லது பாதிக்கப்பட்ட அட்டையை முடக்கவோ மூடவோ அட்டைகள் பக்கத்தின் மூலம் உடனடியாகப் புகாரளிக்க வேண்டும்; புகார் பெறப்படும் முன் செய்யப்பட்ட பரிவர்த்தனைகளுக்கு நீங்கள் பொறுப்பாவீர்கள், பொருந்தும் சட்டம் மற்றும் கீழே உள்ள பிரிவு 10 கட்டுப்படுத்தும் அளவு தவிர.',
    's9_title' => '9. உங்கள் பொறுப்புகள் மற்றும் கணக்குப் பாதுகாப்பு.',
    's9_body' => 'உங்கள் கடவுச்சொல், பரிவர்த்தனை PIN, இரு-காரணி அங்கீகாரக் குறியீடுகள், Ledger-ஐ அணுகப் பயன்படுத்தும் சாதனம் ஆகியவற்றைப் பாதுகாப்பாக வைத்திருப்பதும், யாருடனும் பகிராமல் இருப்பதும் உங்கள் பொறுப்பு. உங்கள் கணக்கு, கடவுச்சொல் அல்லது அட்டை பாதிக்கப்பட்டதாக நம்பினால், அல்லது அடையாளம் தெரியாத பரிவர்த்தனையைக் கவனித்தால், ஆதரவுப் பக்கத்தின் மூலம் உடனடியாக எங்களுக்குத் தெரிவிக்க வேண்டும். உங்கள் தொடர்புத் தகவல், அஞ்சல் முகவரி மற்றும் பதிவில் உள்ள அடையாள ஆவணங்களைப் புதுப்பித்தும் துல்லியமாகவும் வைத்திருக்க ஒப்புக்கொள்கிறீர்கள்.',
    's10_title' => '10. பிழைகள் மற்றும் அங்கீகரிக்கப்படாத பரிவர்த்தனைகள்.',
    's10_body' => 'ஒரு பரிமாற்றம், அட்டைக் கட்டணம் அல்லது பிற பரிவர்த்தனை உங்கள் அனுமதியின்றி செய்யப்பட்டதாக, அல்லது உங்கள் கணக்கு அறிக்கையில் பிழை இருப்பதாக நம்பினால், கூடிய விரைவில், செயல்பாடு வரலாற்றில் முதன்முதலில் தோன்றிய 60 நாட்களுக்குள், ஆதரவைத் தொடர்பு கொள்ளவும். நல்லெண்ணத்துடன் விசாரிப்போம், விசாரணை நிலுவையில் இருக்கும்போது நிதிகளைத் தற்காலிகமாகத் திருப்பி அளிக்கலாம். உறுதிப்படுத்தப்பட்ட அங்கீகரிக்கப்படாத பரிவர்த்தனைக்கான உங்கள் பொறுப்பு பொருந்தும் சட்டம் கோரும் அளவுக்குக் கட்டுப்படுத்தப்படும், நீங்கள் உடனடியாக எங்களுக்குத் தெரிவித்து, உங்கள் உள்நுழைவு விவரங்களைப் பாதுகாப்பதில் மோசடியாகவோ கடும் அலட்சியத்துடனோ செயல்படவில்லை எனில்.',
    's11_title' => '11. தடைசெய்யப்பட்ட பயன்பாடுகள்.',
    's11_body' => 'பணமோசடி, பயங்கரவாத நிதியுதவி, மோசடி அல்லது தடைகளைத் தவிர்த்தல் உட்பட எந்தச் சட்டவிரோத நோக்கத்துக்கும் சேவையைப் பயன்படுத்தமாட்டீர்கள்; சட்டப்படி உரிமையில்லாத நிதிகளை அனுப்பவோ பெறவோ மாட்டீர்கள்; மற்றொரு பயனரின் கணக்கையோ Ledger-இன் அமைப்புகளையோ அங்கீகாரமின்றி அணுக முயலமாட்டீர்கள்; சேவையின் இயல்பான செயல்பாட்டில் குறுக்கிடமாட்டீர்கள் என ஒப்புக்கொள்கிறீர்கள். இந்தப் பிரிவை மீறுவதாக நியாயமாக நம்பப்படும் எந்தப் பரிவர்த்தனையையும் நிராகரிக்கலாம், தாமதப்படுத்தலாம், முடிந்தால் திருப்பலாம் அல்லது புகாரளிக்கலாம், சட்டம் கோரியபடி சட்ட அமலாக்கம் அல்லது ஒழுங்குமுறை அதிகாரிகளுடன் தகவலைப் பகிரலாம்.',
    's12_title' => '12. கணக்கு நிலை, இடைநீக்கம் மற்றும் மூடல்.',
    's12_body' => 'எங்கள் விருப்பப்படி உங்கள் கணக்கை முடக்கலாம், கட்டுப்படுத்தலாம், இடைநீக்கம் செய்யலாம் அல்லது மூடலாம், அல்லது குறிப்பிட்ட பரிவர்த்தனையை நிராகரிக்கலாம் — சட்டத்துக்கு இணங்க, சந்தேகத்துக்குரிய மோசடி அல்லது முறைகேட்டை விசாரிக்க, சட்ட அல்லது ஒழுங்குமுறைக் கோரிக்கைக்குப் பதிலளிக்க, அல்லது உங்களை, மற்றொரு பயனரை அல்லது Ledger-ஐப் பாதுகாக்க அவசியம் என நியாயமாக நம்பும் இடங்களில் உட்பட. இயன்றவரை காரணத்தையும் ஆதரவுப் பக்கம் மூலம் எங்களை எப்படித் தொடர்பு கொள்வது என்பதையும் தெரிவிப்போம். இருப்பு பூஜ்ஜியமாக அல்லது எடுக்கப்பட்டதாக இருந்து, திறந்த விசாரணையோ நிலுவையிலுள்ள பரிவர்த்தனையோ இல்லையெனில், ஆதரவைத் தொடர்பு கொண்டு எப்போது வேண்டுமானாலும் கணக்கை மூடலாம்.',
    's13_title' => '13. சேவை கிடைப்புத்தன்மை; பொறுப்புத் துறப்புகள்.',
    's13_body' => 'சேவையைக் கிடைக்கக்கூடியதாகவும் துல்லியமாகவும் வைத்திருக்க முயல்கிறோம், ஆனால் சேவை "உள்ளபடியே" வழங்கப்படுகிறது, இது எப்போதும் தடையின்றி, பிழையின்றி அல்லது கிடைப்பதாக இருக்கும் என உத்தரவாதம் அளிப்பதில்லை. கூட்டாளர் வங்கி, அட்டை வலையமைப்பு அல்லது இடைநிலை நிறுவனத்தில் ஏற்படும் செயலிழப்புகள், அல்லது தவிர்க்க முடியாத நிகழ்வுகள் உட்பட எங்கள் நியாயமான கட்டுப்பாட்டுக்கு அப்பாற்பட்ட சூழ்நிலைகளால் ஏற்படும் தாமதங்கள் அல்லது தோல்விகளுக்கு நாங்கள் பொறுப்பல்ல. சட்டம் அனுமதிக்கும் முழு அளவில், சேவையைப் பயன்படுத்துவதால் எழும் எந்தக் கோரிக்கைக்கும் Ledger-இன் மொத்தப் பொறுப்பு அந்தக் கோரிக்கைக்குக் காரணமான பரிவர்த்தனையின் தொகைக்குக் கட்டுப்படுத்தப்படும், நுகர்வோர் நிதிக் கணக்குகளைப் பாதுகாக்கும் சட்டம் விரிவான தீர்வைக் கோரும் இடங்கள் தவிர.',
    's14_title' => '14. தகராறு தீர்வு.',
    's14_body' => 'உங்களுக்கும் Ledger-க்கும் இடையே கருத்து வேறுபாடு எழுந்தால், நேரடியாகத் தீர்க்க முயல முதலில் ஆதரவைத் தொடர்பு கொள்ளும்படி கேட்கிறோம் — பெரும்பாலான சிக்கல்கள் இப்படியே தீர்க்கப்படுகின்றன. தகராறு முறைசாரா முறையில் தீர்க்கப்படவில்லை எனில், பொருந்தும் சட்டத்தின் கீழ் கிடைக்கும் எந்தத் தீர்வையும் எந்தத் தரப்பும் நாடலாம். இந்த விதிமுறைகளில் உள்ள எதுவும், நுகர்வோர் பாதுகாப்புச் சட்டத்தின் கீழ் உங்கள் மாநில அல்லது கூட்டாட்சி ஒழுங்குமுறையாளரிடம் தகராறை எழுப்பும் உங்கள் உரிமையைக் கட்டுப்படுத்தாது.',
    's15_title' => '15. தனியுரிமை.',
    's15_body' => 'உங்கள் தனிப்பட்ட மற்றும் நிதித் தகவலை நாங்கள் கையாளும் விதம் — என்ன சேகரிக்கிறோம், எப்படிப் பயன்படுத்துகிறோம், யாருடன் பகிரலாம் (கூட்டாளர் வங்கிகள், அடையாளச் சரிபார்ப்பு வழங்குநர்கள், சேவையை இயக்கத் தேவையான அட்டை வலையமைப்புகள் போன்றவை), உங்களுக்குக் கிடைக்கும் தேர்வுகள் — எங்கள் தனியுரிமை நடைமுறைகளில் விவரிக்கப்பட்டுள்ளது. சேவையை இயக்கவும், பாதுகாக்கவும், அதற்குப் பொருந்தும் சட்டத்துக்கு இணங்கவும் மட்டுமே உங்கள் அடையாள மற்றும் கணக்குத் தகவலைப் பயன்படுத்துகிறோம், உங்கள் தனிப்பட்ட தகவலை விற்பதில்லை.',
    's16_title' => '16. இந்த விதிமுறைகளில் மாற்றங்கள்.',
    's16_body' => 'சேவை, கூட்டாளர் வங்கிகள் அல்லது பொருந்தும் சட்டத்தில் ஏற்படும் மாற்றங்களைப் பிரதிபலிக்க இந்த விதிமுறைகளை அவ்வப்போது புதுப்பிக்கலாம். முக்கிய மாற்றம் செய்யும்போது, மேலே உள்ள "கடைசியாகப் புதுப்பிக்கப்பட்டது" தேதியைப் புதுப்பிப்போம், சட்டம் கோரும் இடங்களில் கூடுதல் அறிவிப்பு வழங்குவோம். மாற்றம் நடைமுறைக்கு வந்த பிறகும் சேவையைத் தொடர்ந்து பயன்படுத்தினால், புதுப்பிக்கப்பட்ட விதிமுறைகளை ஏற்கிறீர்கள் என்று பொருள்; மாற்றத்துடன் உடன்படவில்லை எனில், சேவையைப் பயன்படுத்துவதை நிறுத்தி கணக்கை மூட வேண்டும்.',
    's17_title' => '17. ஆளும் சட்டம்.',
    's17_body' => 'சட்ட முரண்பாட்டுக் கொள்கைகளைக் கருதாமல், இந்த விதிமுறைகள் அமெரிக்காவின் சட்டங்களாலும் Ledger-இன் செயல்பாடுகளின் தலைமையகம் அமைந்துள்ள மாநிலத்தின் சட்டங்களாலும் நிர்வகிக்கப்படுகின்றன, நீங்கள் வசிக்கும் அதிகார வரம்பு வேறு சட்டத்தைப் பொருந்தச் செய்ய வேண்டும் என்று கோரும் இடங்கள் தவிர.',
    's18_title' => '18. எங்களைத் தொடர்பு கொள்ளுங்கள்.',
    's18_body' => 'இந்த விதிமுறைகள், உங்கள் கணக்கு அல்லது குறிப்பிட்ட பரிவர்த்தனை பற்றிய கேள்விகளை :support_link பக்கம் மூலம் எப்போது வேண்டுமானாலும் அனுப்பலாம்.',
